def copy_doubles(X, Y, incX, incY):
    if not isinstance(X, list) or not isinstance(Y, list):
        raise TypeError("X and Y must be lists")
    if not all(isinstance(x, (int, float)) for x in X) or not all(isinstance(y, (int, float)) for y in Y):
        raise TypeError("X and Y must contain numeric values")
    if len(Y) < len(X):
        raise ValueError("Y must be at least as long as X")

    n = len(X)

    # Load the dynamic libraries in the specified order
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except Exception as e:
        raise RuntimeError("Failed to load GSL libraries") from e

    # Define function prototype
    try:
        cblas_dcopy = gsl.cblas_dcopy
        cblas_dcopy.argtypes = [
            ctypes.c_int,                     # n
            ctypes.POINTER(ctypes.c_double),  # x
            ctypes.c_int,                     # incx
            ctypes.POINTER(ctypes.c_double),  # y
            ctypes.c_int                      # incy
        ]
    except AttributeError as e:
        raise RuntimeError("Failed to define cblas_dcopy function prototype") from e

    # Convert Python lists to C arrays
    try:
        x_array = (ctypes.c_double * len(X))(*X)
        y_array = (ctypes.c_double * len(Y))(*Y)
    except Exception as e:
        raise RuntimeError("Failed to create C arrays") from e

    # Call the function
    cblas_dcopy(n, x_array, incX, y_array, incY)

    # Update Y in place
    for i in range(len(Y)):
        Y[i] = y_array[i]

