    gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int

    matrix_type = ctypes.c_double * (n * n)
    c_matrix = matrix_type()
    for i in range(n):
        for j in range(n):
            c_matrix[i * n + j] = matrix[i][j]

    status = gsl.gsl_linalg_cholesky_decomp(c_matrix, n)
    if status != 0:
        raise RuntimeError("Cholesky decomposition failed.")

    result = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1):
            result[i][j] = c_matrix[i * n + j]
    return result

